describe("exceptions propagate across calls", () => {
  const cases: Array<[string, Program, { output: string[]; error: string | null }]> = [
    ["function a(){ b() } function b(){ c() } function c(){ throw new Error(\"deep\") } try { a() } catch (e) { print(e.message) }",
      program({
        type: "Program",
        body: [
          {
            type: "FunctionDeclaration",
            id: {type: "Identifier", name: "a"},
            params: [],
            body: {type: "BlockStatement", body: [{type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "b"}, arguments: []}}]},
            expression: false,
          },
          {
            type: "FunctionDeclaration",
            id: {type: "Identifier", name: "b"},
            params: [],
            body: {type: "BlockStatement", body: [{type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "c"}, arguments: []}}]},
            expression: false,
          },
          {
            type: "FunctionDeclaration",
            id: {type: "Identifier", name: "c"},
            params: [],
            body: {
              type: "BlockStatement",
              body: [{type: "ThrowStatement", argument: {type: "NewExpression", callee: {type: "Identifier", name: "Error"}, arguments: [{type: "Literal", value: "deep", raw: "\"deep\""}]}}],
            },
            expression: false,
          },
          {
            type: "TryStatement",
            block: {type: "BlockStatement", body: [{type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "a"}, arguments: []}}]},
            handler: {
              type: "CatchClause",
              param: {type: "Identifier", name: "e"},
              body: {
                type: "BlockStatement",
                body: [
                  {
                    type: "ExpressionStatement",
                    expression: {
                      type: "CallExpression",
                      callee: {type: "Identifier", name: "print"},
                      arguments: [{type: "MemberExpression", object: {type: "Identifier", name: "e"}, property: {type: "Identifier", name: "message"}, computed: false}],
                    },
                  },
                ],
              },
            },
            finalizer: null,
          },
        ],
        sourceType: "script",
      }),
      { output: ["deep"], error: null }],
    ["function risky(){ throw new TypeError(\"nope\") } function safe(){ try { risky() } catch (e) { return \"handled \" + e.name } } print(safe())",
      program({
        type: "Program",
        body: [
          {
            type: "FunctionDeclaration",
            id: {type: "Identifier", name: "risky"},
            params: [],
            body: {
              type: "BlockStatement",
              body: [{type: "ThrowStatement", argument: {type: "NewExpression", callee: {type: "Identifier", name: "TypeError"}, arguments: [{type: "Literal", value: "nope", raw: "\"nope\""}]}}],
            },
            expression: false,
          },
          {
            type: "FunctionDeclaration",
            id: {type: "Identifier", name: "safe"},
            params: [],
            body: {
              type: "BlockStatement",
              body: [
                {
                  type: "TryStatement",
                  block: {type: "BlockStatement", body: [{type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "risky"}, arguments: []}}]},
                  handler: {
                    type: "CatchClause",
                    param: {type: "Identifier", name: "e"},
                    body: {
                      type: "BlockStatement",
                      body: [
                        {
                          type: "ReturnStatement",
                          argument: {
                            type: "BinaryExpression",
                            left: {type: "Literal", value: "handled ", raw: "\"handled \""},
                            operator: "+",
                            right: {type: "MemberExpression", object: {type: "Identifier", name: "e"}, property: {type: "Identifier", name: "name"}, computed: false},
                          },
                        },
                      ],
                    },
                  },
                  finalizer: null,
                },
              ],
            },
            expression: false,
          },
          {
            type: "ExpressionStatement",
            expression: {type: "CallExpression", callee: {type: "Identifier", name: "print"}, arguments: [{type: "CallExpression", callee: {type: "Identifier", name: "safe"}, arguments: []}]},
          },
        ],
        sourceType: "script",
      }),
      { output: ["handled TypeError"], error: null }],
    ["null.x",
      program({
        type: "Program",
        body: [{type: "ExpressionStatement", expression: {type: "MemberExpression", object: {type: "Literal", value: null, raw: "null"}, property: {type: "Identifier", name: "x"}, computed: false}}],
        sourceType: "script",
      }),
      { output: [], error: "TypeError" }],
    ["undeclaredAtTop",
      program({type: "Program", body: [{type: "ExpressionStatement", expression: {type: "Identifier", name: "undeclaredAtTop"}}], sourceType: "script"}),
      { output: [], error: "ReferenceError" }],
    ["throw new Error(\"escapes to the top\")",
      program({
        type: "Program",
        body: [
          {
            type: "ThrowStatement",
            argument: {type: "NewExpression", callee: {type: "Identifier", name: "Error"}, arguments: [{type: "Literal", value: "escapes to the top", raw: "\"escapes to the top\""}]},
          },
        ],
        sourceType: "script",
      }),
      { output: [], error: "Error" }],
    ["throw \"a bare string\"",
      program({type: "Program", body: [{type: "ThrowStatement", argument: {type: "Literal", value: "a bare string", raw: "\"a bare string\""}}], sourceType: "script"}),
      { output: [], error: "a bare string" }],
    ["function f(){ throw new RangeError(\"x\") } f()",
      program({
        type: "Program",
        body: [
          {
            type: "FunctionDeclaration",
            id: {type: "Identifier", name: "f"},
            params: [],
            body: {
              type: "BlockStatement",
              body: [{type: "ThrowStatement", argument: {type: "NewExpression", callee: {type: "Identifier", name: "RangeError"}, arguments: [{type: "Literal", value: "x", raw: "\"x\""}]}}],
            },
            expression: false,
          },
          {type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "f"}, arguments: []}},
        ],
        sourceType: "script",
      }),
      { output: [], error: "RangeError" }],
  ];
  it.each(cases)("%s", (_source, ast, expected) => {
    expect(evaluate(ast)).toEqual(expected);
  });
});
